The program finds every `name <- expression` statement in the input, rewrites `mod` as Python's `%`, and evaluates the statements in order. It then prints the final values in the requested format. Lines without `<-`, such as the instruction text, are ignored.

```python
import sys
import re

def main():
    text = sys.stdin.read()
    env = {}
    # Match statements of the form: NAME <- EXPR ;  (terminated by ';' or end of line)
    pattern = re.compile(r'([A-Za-z_]\w*)\s*<-\s*([^;\n]+)')
    for m in pattern.finditer(text):
        name = m.group(1)
        expr = m.group(2).strip()
        if not expr:
            continue
        py_expr = re.sub(r'\bmod\b', '%', expr)
        # Only allow safe characters: identifiers, digits, operators, parens, spaces
        if not re.fullmatch(r'[\w\s+\-*/%()]+', py_expr):
            continue
        # Make sure all identifiers referenced are known (default 0)
        for ident in re.findall(r'[A-Za-z_]\w*', py_expr):
            if ident not in env:
                env[ident] = 0
        try:
            val = eval(py_expr, {"__builtins__": {}}, dict(env))
        except Exception:
            continue
        env[name] = val

    order = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'TMP']
    parts = ["%s ?= %s;" % (v, env.get(v, 0)) for v in order]
    print(" ".join(parts))

if __name__ == "__main__":
    main()
